#include "stdlib/stats/base/dists/rayleigh/logpdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/constants/float64/pinf.h"
#include "stdlib/constants/float64/ninf.h"
#include "stdlib/constants/float64/smallest_normal.h"

/**
* Evaluates the natural logarithm of the probability density function (PDF) for a Rayleigh distribution with scale parameter `sigma` at a value `x`.
*
* @param x        input value
* @param sigma    scale parameter
* @return         evaluated logPDF
*
* @example
* double y = stdlib_base_dists_rayleigh_logpdf( 0.3, 1.0 );
* // returns ~-1.249
*/
double stdlib_base_dists_rayleigh_logpdf( const double x, const double sigma ) {
	double s2i;
	double lq;
	double s2;
	double x2;
	double r;
	double q;
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( sigma ) ||
		sigma < 0.0
	) {
		return 0.0/0.0; // NaN
	}
	if ( sigma == 0.0 ) {
		return ( x == 0.0 ) ? STDLIB_CONSTANT_FLOAT64_PINF : STDLIB_CONSTANT_FLOAT64_NINF;
	}
	if ( x < 0.0 || x == STDLIB_CONSTANT_FLOAT64_PINF ) {
		return STDLIB_CONSTANT_FLOAT64_NINF;
	}
	s2 = stdlib_base_pow( sigma, 2.0 );
	s2i = 1.0 / s2;
	x2 = stdlib_base_pow( x, 2.0 );
	q = s2i * x;
	if (
		s2 >= STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL &&
		s2 < STDLIB_CONSTANT_FLOAT64_PINF &&
		x2 < STDLIB_CONSTANT_FLOAT64_PINF &&
		q >= STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL
	) {
		return stdlib_base_ln( q ) - x2 / ( 2.0 * s2 );
	}
	// For `sigma` or `x` far from `1`, forming `sigma^2` or `x^2` overflows or underflows, so evaluate via the ratio `x/sigma` instead. `ln( x/sigma^2 )` is taken directly while that ratio is normal, as subtracting two large logarithms cancels when `x` is close to `sigma^2`...
	r = x / sigma;
	q = r / sigma;
	if ( q >= STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL && q < STDLIB_CONSTANT_FLOAT64_PINF ) {
		lq = stdlib_base_ln( q );
	} else if ( r >= STDLIB_CONSTANT_FLOAT64_SMALLEST_NORMAL ) {
		lq = stdlib_base_ln( r ) - stdlib_base_ln( sigma );
	} else {
		lq = ( stdlib_base_ln( x ) - stdlib_base_ln( sigma ) ) - stdlib_base_ln( sigma );
	}
	return lq - ( 0.5 * r * r );
}
